import time
import unittest

from rota.check import problems
from rota.planner import make_rota

HARD = [{"staff": [{"name": "Ada", "max_shifts": 4, "unavailable": ["mon-late"], "skills": ["first-aid"]}, {"name": "Bo", "max_shifts": 3, "unavailable": ["mon-late", "thu-early"], "skills": ["first-aid"]}, {"name": "Cy", "max_shifts": 3, "unavailable": ["mon-early"], "skills": []}, {"name": "Dee", "max_shifts": 2, "unavailable": ["thu-late"], "skills": []}, {"name": "Eli", "max_shifts": 3, "unavailable": [], "skills": []}, {"name": "Fay", "max_shifts": 4, "unavailable": ["tue-early"], "skills": []}, {"name": "Gus", "max_shifts": 2, "unavailable": ["tue-late"], "skills": []}], "shifts": [{"id": "mon-early", "day": 0, "slot": "early", "needs": 1}, {"id": "mon-late", "day": 0, "slot": "late", "needs": 2}, {"id": "mon-night", "day": 0, "slot": "night", "needs": 2}, {"id": "tue-early", "day": 1, "slot": "early", "needs": 2}, {"id": "tue-late", "day": 1, "slot": "late", "needs": 2}, {"id": "tue-night", "day": 1, "slot": "night", "needs": 1}, {"id": "wed-early", "day": 2, "slot": "early", "needs": 1}, {"id": "wed-late", "day": 2, "slot": "late", "needs": 2, "skill": "first-aid"}, {"id": "wed-night", "day": 2, "slot": "night", "needs": 2, "skill": "first-aid"}, {"id": "thu-early", "day": 3, "slot": "early", "needs": 2, "skill": "first-aid"}, {"id": "thu-late", "day": 3, "slot": "late", "needs": 2, "skill": "first-aid"}, {"id": "thu-night", "day": 3, "slot": "night", "needs": 2}]}, {"staff": [{"name": "Ada", "max_shifts": 4, "unavailable": ["mon-night", "thu-late"], "skills": ["first-aid"]}, {"name": "Bo", "max_shifts": 2, "unavailable": ["wed-late"], "skills": []}, {"name": "Cy", "max_shifts": 3, "unavailable": ["wed-late", "wed-night", "thu-early", "thu-night"], "skills": []}, {"name": "Dee", "max_shifts": 4, "unavailable": ["tue-early", "thu-night"], "skills": ["first-aid"]}, {"name": "Eli", "max_shifts": 3, "unavailable": ["tue-night", "wed-late", "thu-early"], "skills": []}, {"name": "Fay", "max_shifts": 3, "unavailable": ["tue-late", "thu-early", "thu-night"], "skills": []}, {"name": "Gus", "max_shifts": 2, "unavailable": ["mon-night"], "skills": []}], "shifts": [{"id": "mon-early", "day": 0, "slot": "early", "needs": 2, "skill": "first-aid"}, {"id": "mon-late", "day": 0, "slot": "late", "needs": 2, "skill": "first-aid"}, {"id": "mon-night", "day": 0, "slot": "night", "needs": 2, "skill": "first-aid"}, {"id": "tue-early", "day": 1, "slot": "early", "needs": 1}, {"id": "tue-late", "day": 1, "slot": "late", "needs": 2}, {"id": "tue-night", "day": 1, "slot": "night", "needs": 2}, {"id": "wed-early", "day": 2, "slot": "early", "needs": 2}, {"id": "wed-late", "day": 2, "slot": "late", "needs": 2, "skill": "first-aid"}, {"id": "wed-night", "day": 2, "slot": "night", "needs": 1}, {"id": "thu-early", "day": 3, "slot": "early", "needs": 1}, {"id": "thu-late", "day": 3, "slot": "late", "needs": 2}, {"id": "thu-night", "day": 3, "slot": "night", "needs": 2}]}, {"staff": [{"name": "Ada", "max_shifts": 3, "unavailable": ["thu-night"], "skills": []}, {"name": "Bo", "max_shifts": 2, "unavailable": ["mon-early", "mon-night", "tue-early", "wed-late", "thu-late"], "skills": ["first-aid"]}, {"name": "Cy", "max_shifts": 3, "unavailable": ["mon-late", "wed-early", "wed-late", "wed-night", "thu-early"], "skills": ["first-aid"]}, {"name": "Dee", "max_shifts": 4, "unavailable": ["tue-late", "thu-late"], "skills": []}, {"name": "Eli", "max_shifts": 2, "unavailable": ["wed-late"], "skills": []}, {"name": "Fay", "max_shifts": 4, "unavailable": ["tue-early", "tue-night", "wed-early", "wed-night", "thu-early", "thu-late"], "skills": []}, {"name": "Gus", "max_shifts": 4, "unavailable": ["mon-night", "thu-early"], "skills": []}], "shifts": [{"id": "mon-early", "day": 0, "slot": "early", "needs": 2, "skill": "first-aid"}, {"id": "mon-late", "day": 0, "slot": "late", "needs": 2}, {"id": "mon-night", "day": 0, "slot": "night", "needs": 2, "skill": "first-aid"}, {"id": "tue-early", "day": 1, "slot": "early", "needs": 1}, {"id": "tue-late", "day": 1, "slot": "late", "needs": 1}, {"id": "tue-night", "day": 1, "slot": "night", "needs": 1}, {"id": "wed-early", "day": 2, "slot": "early", "needs": 1}, {"id": "wed-late", "day": 2, "slot": "late", "needs": 1}, {"id": "wed-night", "day": 2, "slot": "night", "needs": 2, "skill": "first-aid"}, {"id": "thu-early", "day": 3, "slot": "early", "needs": 2}, {"id": "thu-late", "day": 3, "slot": "late", "needs": 2, "skill": "first-aid"}, {"id": "thu-night", "day": 3, "slot": "night", "needs": 2}]}]
IMPOSSIBLE = {"staff": [{"name": "Ada", "max_shifts": 5, "unavailable": [], "skills": ["first-aid"]}, {"name": "Bo", "max_shifts": 5, "unavailable": [], "skills": []}, {"name": "Cy", "max_shifts": 5, "unavailable": [], "skills": []}, {"name": "Dee", "max_shifts": 5, "unavailable": [], "skills": []}, {"name": "Eli", "max_shifts": 5, "unavailable": [], "skills": []}], "shifts": [{"id": "mon-late", "day": 0, "slot": "late", "needs": 2}, {"id": "mon-night", "day": 0, "slot": "night", "needs": 2, "skill": "first-aid"}, {"id": "tue-early", "day": 1, "slot": "early", "needs": 2, "skill": "first-aid"}, {"id": "tue-late", "day": 1, "slot": "late", "needs": 1}]}


class RotaTest(unittest.TestCase):
    def test_weeks_a_first_come_fill_gets_wrong(self):
        for index, week in enumerate(HARD):
            with self.subTest(week=index):
                started = time.perf_counter()
                rota = make_rota(week["staff"], week["shifts"])
                self.assertLess(time.perf_counter() - started, 10)
                self.assertIsNotNone(rota, "this week can be filled")
                self.assertEqual(problems(rota, week["staff"], week["shifts"]), [])

    def test_a_week_that_cant_be_filled(self):
        self.assertIsNone(make_rota(IMPOSSIBLE["staff"], IMPOSSIBLE["shifts"]))
